def fill(self, coord, weight=1):
    """Fill histogram at *coord* with the given *weight*.

    Coordinates outside the histogram edges are ignored.
    """
    if not (self._min <= coord <= self._max):
        return

    try:
        index = int((coord - self._min) / self._bin_width)
        if index < self._num_bins:
            self._hist[index] += weight
    except (TypeError, ValueError):
        raise ValueError("Invalid coordinate value")

def fill(self, coord, weight=1):
    """
    Fill histogram at *coord* with the given *weight*.

    Coordinates outside the histogram edges are ignored.
    """
    if self.edges is None:
        raise ValueError("Histogram edges not set")

    if isinstance(coord, (int, np.integer)):
        coord = [coord]

    if not isinstance(coord, (list, np.ndarray)):
        raise ValueError("Invalid coordinate type")

    for c in coord:
        if c < self.edges[0] or c > self.edges[-1]:
            continue

        bin_index = bisect.bisect_right(self.edges, c) - 1
        self.values[bin_index] += weight

def fill(self, coord, weight=1):
    """Fill histogram at *coord* with the given *weight*.

    Coordinates outside the histogram edges are ignored.
    """
    if coord < self._left_edge or coord > self._right_edge:
        return
    bin_index = int((coord - self._left_edge) / self._bin_width)
    if bin_index >= len(self._histogram):
        return
    self._histogram[bin_index] += weight

